import { NextResponse } from 'next/server'
import type { NextRequest } from 'next/server'

export function middleware(request: NextRequest) {
  // Generate a unique request ID
  const requestId = crypto.randomUUID()

  // Clone the request headers and set the new header
  const requestHeaders = new Headers(request.headers)
  requestHeaders.set('x-request-id', requestId)

  // Create the response using NextResponse.next()
  // Passing the modified request headers allows the header to be available in Server Components/API Routes
  const response = NextResponse.next({
    request: {
      headers: requestHeaders,
    },
  })

  // Set the custom header on the response
  response.headers.set('x-request-id', requestId)

  // Log the request pathname to the console
  console.log(`Request Pathname: ${request.nextUrl.pathname}`)

  return response
}

export const config = {
  matcher: [
    /*
     * Match all request paths except for the ones starting with:
     * - api (API routes)
     * - _next/static (static files)
     * - _next/image (image optimization files)
     * - favicon.ico (favicon file)
     */
    '/((?!api|_next/static|_next/image|favicon.ico).*)',
  ],
}

